(function(root){
 const D=root.RoadmapData||(typeof require!=='undefined'?require('./calculus-data.js').data:null),R=root.TIRecipes||(typeof require!=='undefined'?require('./ti-recipes.js'):null);
 const original=[...D.problems];
 function numericStep(source,group,mode){const fields=source.fields.map((field,i)=>({...field,value:group.rows[i].value}));return {...source,fields,ti84:{mode,rows:group.rows.map((row,i)=>({...row,label:fields[i].label}))},worked:[{text:source.why,equations:[]},{text:group.note,equations:[]}],solution:fields.map(f=>f.label+' = '+f.value).join('; ')};}
 for(const base of original){
  base.familyId=base.id;base.familyName=base.typeName;base.exampleNumber=0;
  const first=R.recipe(base.id);let index=0;base.steps=base.steps.map(step=>step.fields?numericStep(step,first.groups[index++],first.mode):step);base.ti84Mode=first.mode;
  for(const number of [1,2]){const r=R.recipe(base.id,number),sources=base.steps.filter(s=>s.fields),variant={id:base.id+'-practice-'+number,familyId:base.id,familyName:base.typeName,exampleNumber:number,group:base.group,title:base.title,typeName:base.typeName+' · example '+(number+1),workspace:base.workspace,description:base.description,prompt:r.prompt+' <strong>Original numerical variation.</strong>',ti84Mode:r.mode,graph:R.graphFor(r),steps:r.groups.map((group,i)=>{const fields=sources[i].fields.map(f=>({...f,label:base.id==='calc-bounds'?f.label.replace('F(3)','F(upper)').replace('F(1)','F(lower)'):f.label}));return numericStep({...sources[i],fields,why:group.note,question:'Calculate '+fields.map(f=>f.label).join(', ')+'.',hint:{reminder:group.note,inputs:'Use this example’s stated data and your checked results. Keep values stored at full precision.'},reveals:[]},group,r.mode);})};D.problems.push(variant);}
 }
 for(const p of D.problems){let memory=[];for(const step of p.steps){if(!step.ti84)continue;step.ti84.memory=[...memory];memory.push(...step.ti84.rows.map(row=>({store:row.store,label:row.label})));}if(!p.exampleNumber||!p.graph)continue;const r=R.recipe(p.familyId,p.exampleNumber),proof=r.proof;
  if(p.familyId==='moments'||p.familyId==='couples'){const F=proof.f,length=Math.hypot(...F),u=F.map(x=>x/length),start=proof.kind==='couple'?proof.b:[0,0,0],point=proof.kind==='couple'?proof.p:proof.r,d=point.map((x,i)=>x-start[i]),projection=d.reduce((s,x,i)=>s+x*u[i],0),foot=point.map((x,i)=>x-projection*u[i]),arm=foot.map((x,i)=>x-start[i]),armLength=Math.hypot(...arm),i=p.steps.length-1;p.steps[i].reveals=[{start,end:foot,label:'d = '+Number(armLength.toPrecision(4))+' m',color:'#d6b6ff',arrow:true,derived:true,measurementStep:i,rightAngle:{origin:foot,first:arm.map(x=>-x/armLength),second:u}}];}
  if(p.familyId==='projection-perpendicular'){const u=proof.d.map(x=>x/Math.hypot(...proof.d)),s=proof.f.reduce((sum,x,i)=>sum+x*u[i],0),parallel=u.map(x=>s*x);p.steps[2].reveals=[{start:[0,0,0],end:parallel,label:'parallel force (N)',color:'#d6b6ff',arrow:true,derived:true,measurementStep:2}];p.steps[3].reveals=[{start:parallel,end:proof.f,label:'perpendicular remainder (N)',color:'#d6b6ff',arrow:true,derived:true,measurementStep:3}];}
 }
 const api={data:D,families:original.map(p=>p.id)};root.PracticeBank=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window!=='undefined'?window:globalThis);
